def gen(rng):
    def fmt(g):
        return f"{len(g)} {len(g[0])}\n" + "\n".join(" ".join(map(str, row)) for row in g)

    def pat(t):
        if t == 0:
            return 1
        return 2 if t % 2 else 0

    def plant(g, i, j, di, dj, k):
        for t in range(k):
            x, y = i + t * di, j + t * dj
            if 0 <= x < len(g) and 0 <= y < len(g[0]):
                g[x][y] = pat(t)

    tests = [
        fmt([[1]]), fmt([[0]]), fmt([[5, 1, 5]]), fmt([[1], [2], [0]]), fmt([[1, 1], [1, 1]]),
        fmt([[2, 0], [0, 2]]), fmt([[1, 2], [2, 1]]), fmt([[1, 2, 0], [2, 2, 2], [0, 2, 1]]),
        fmt([[1, 2, 0, 2, 0, 2]]),
    ]
    for _ in range(30):
        r, c = rng.randint(1, 7), rng.randint(1, 7)
        g = [[rng.choice([0, 1, 2, 2, 0, 1, 3]) for _ in range(c)] for _ in range(r)]
        tests.append(fmt(g))
    for _ in range(25):
        r, c = rng.randint(2, 8), rng.randint(2, 8)
        g = [[rng.randint(0, 3) for _ in range(c)] for _ in range(r)]
        for _ in range(rng.randint(1, 3)):
            plant(g, rng.randrange(r), rng.randrange(c), rng.choice([-1, 1]), rng.choice([-1, 1]), rng.randint(1, 8))
        tests.append(fmt(g))
    N = 500
    tests.append(fmt([[pat(i) for j in range(N)] for i in range(N)]))
    tests.append(fmt([[pat(j) for j in range(N)] for i in range(N)]))
    tests.append(fmt([[1] * N for _ in range(N)]))
    tests.append(fmt([[rng.choice([0, 1, 2]) for _ in range(N)] for _ in range(N)]))
    g = [[rng.choice([0, 2, 2, 3]) for _ in range(N)] for _ in range(N)]
    for _ in range(300):
        plant(g, rng.randrange(N), rng.randrange(N), rng.choice([-1, 1]), rng.choice([-1, 1]), rng.randint(1, 400))
    tests.append(fmt(g))
    return tests

